const seed={employees:[{id:'e1',name:'Aarav Sharma',skill:'Machine Operator',location:'Pune',status:'Available'},{id:'e2',name:'Meera Patel',skill:'Housekeeping',location:'Mumbai',status:'Placed'},{id:'e3',name:'Rohan Das',skill:'Warehouse Associate',location:'Ahmedabad',status:'Available'},{id:'e4',name:'Priya Nair',skill:'Quality Inspector',location:'Chennai',status:'Interviewing'},{id:'e5',name:'Kabir Singh',skill:'Kitchen Assistant',location:'Delhi',status:'Available'}],firms:[{id:'f1',name:'Sample Precision Works',sector:'Manufacturing',location:'Pune',contact:'Hiring Team',status:'Active'},{id:'f2',name:'Sample Horizon Hotels',sector:'Hospitality',location:'Mumbai',contact:'People Operations',status:'Active'},{id:'f3',name:'Sample Industrial Hub',sector:'Industrial',location:'Ahmedabad',contact:'Workforce Desk',status:'Active'}],jobs:[{id:'j1',title:'Machine Operator',firm:'f1',sector:'Manufacturing',location:'Pune',salary:'₹18,000–24,000 / month',vacancies:12,status:'Open'},{id:'j2',title:'Housekeeping Associate',firm:'f2',sector:'Hospitality',location:'Mumbai',salary:'₹14,000–18,000 / month',vacancies:8,status:'Open'},{id:'j3',title:'Warehouse Associate',firm:'f3',sector:'Industrial',location:'Ahmedabad',salary:'₹16,000–21,000 / month',vacancies:15,status:'Open'},{id:'j4',title:'Quality Inspector',firm:'f1',sector:'Manufacturing',location:'Pune',salary:'₹20,000–28,000 / month',vacancies:4,status:'Open'},{id:'j5',title:'Kitchen Assistant',firm:'f2',sector:'Hospitality',location:'Mumbai',salary:'₹15,000–20,000 / month',vacancies:6,status:'Open'},{id:'j6',title:'Packing Assistant',firm:'f3',sector:'Industrial',location:'Ahmedabad',salary:'₹13,000–17,000 / month',vacancies:10,status:'Open'}],enquiries:[]};

// Fictional client-demo roles. Merge once so existing browser edits are preserved.
const additionalFirms=[{"id":"f4","name":"Sample Care Hospital","sector":"Healthcare","location":"Pune","contact":"Recruitment Desk","status":"Active"},{"id":"f5","name":"Sample Business Services","sector":"Business Services","location":"Delhi","contact":"People Team","status":"Active"}];
const additionalJobs=[{"id":"additional-role-1","title":"General Manager","sector":"Business Services","firm":"f5","location":"Delhi","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-2","title":"Head Chef","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-3","title":"Chef","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-4","title":"House Keeping Staff","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-5","title":"Kitchen Staffs","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-6","title":"Accounts","sector":"Business Services","firm":"f5","location":"Delhi","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-7","title":"Front Office Manager","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-8","title":"Captain","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-9","title":"Room Attendant","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-10","title":"Steward","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-11","title":"Carpenter","sector":"Industrial","firm":"f3","location":"Ahmedabad","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-12","title":"Electrician","sector":"Industrial","firm":"f3","location":"Ahmedabad","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-13","title":"Reception","sector":"Hospitality","firm":"f2","location":"Mumbai","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-14","title":"Nursing Staff","sector":"Healthcare","firm":"f4","location":"Pune","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-15","title":"Manager","sector":"Business Services","firm":"f5","location":"Delhi","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-16","title":"Radiologist","sector":"Healthcare","firm":"f4","location":"Pune","salary":"Discuss during interview","vacancies":1,"status":"Open"},{"id":"additional-role-17","title":"Management Staff","sector":"Business Services","firm":"f5","location":"Delhi","salary":"Discuss during interview","vacancies":1,"status":"Open"}];
const mergeDemoSeed=(source)=>{const merged=structuredClone(source);for(const firm of additionalFirms)if(!merged.firms.some(f=>f.id===firm.id))merged.firms.push(structuredClone(firm));for(const job of additionalJobs)if(!merged.jobs.some(j=>j.id===job.id))merged.jobs.push(structuredClone(job));return merged;};
const key='resourcify-demo-v1';let db;let storageAvailable=true;try{db=JSON.parse(localStorage.getItem(key))||mergeDemoSeed(seed);if(!['employees','firms','jobs','enquiries'].every(k=>Array.isArray(db[k])))throw Error('Invalid data')}catch{db=mergeDemoSeed(seed)}let tab='employees',editId=null,mode='record',applicationJob=null;
const $=s=>document.querySelector(s);const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const firmName=id=>db.firms.find(f=>f.id===id)?.name||'Unassigned firm';
function save(){try{localStorage.setItem(key,JSON.stringify(db));return true}catch{storageAvailable=false;$('#crm-status').textContent='Browser storage is unavailable. Changes last only while this page remains open.';return false}}
function renderJobs(){const q=$('#job-search').value.toLowerCase(),sector=$('#sector-filter').value;const jobs=db.jobs.filter(j=>j.status==='Open'&&(!sector||j.sector===sector)&&[j.title,j.location,firmName(j.firm)].join(' ').toLowerCase().includes(q));$('#job-list').innerHTML=jobs.length?jobs.map(j=>`<article class="job"><span class="tag">${escapeHtml(j.sector)}</span><h3>${escapeHtml(j.title)}</h3><p>${escapeHtml(firmName(j.firm))}<br>${escapeHtml(j.location)} · ${Number(j.vacancies)} positions</p><div class="job-bottom"><span style="font-size:12px">${escapeHtml(j.salary)}</span><button class="outline" data-apply="${escapeHtml(j.id)}">Apply ↗</button></div></article>`).join(''):'<p class="empty">No openings match your search. Try another role or industry.</p>'}
const config={employees:{singular:'employee',fields:[['name','Full name'],['skill','Role / skill'],['location','Location'],['status','Status',['Available','Interviewing','Placed']]]},firms:{singular:'firm',fields:[['name','Firm name'],['sector','Industry',['Manufacturing','Hospitality','Industrial','Healthcare','Business Services']],['location','Location'],['contact','Contact person'],['status','Status',['Active','Inactive']]]},jobs:{singular:'opening',fields:[['title','Job title'],['firm','Firm','firms'],['sector','Industry',['Manufacturing','Hospitality','Industrial','Healthcare','Business Services']],['location','Location'],['salary','Salary range'],['vacancies','Number of positions','number'],['status','Status',['Open','Closed']]]},enquiries:{singular:'enquiry',fields:[['name','Name'],['company','Company / opportunity'],['email','Email','email'],['requirement','Requirement'],['status','Status',['New','Contacted','Resolved']]]}};
function renderCRM(){const opened=db.jobs.filter(j=>j.status==='Open');$('#metrics').innerHTML=[[db.employees.length,'Employee records'],[db.firms.filter(f=>f.status==='Active').length,'Active firms'],[opened.length,'Open roles'],[opened.reduce((a,j)=>a+Number(j.vacancies),0),'Available positions']].map(([n,t])=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)});$('#add').textContent='+ Add '+config[tab].singular;const fields=config[tab].fields;$('#table-head').innerHTML='<tr>'+fields.map(f=>`<th scope="col">${escapeHtml(f[1])}</th>`).join('')+'<th scope="col">Actions</th></tr>';const q=$('#crm-search').value.toLowerCase();const rows=db[tab].filter(r=>fields.map(f=>f[0]==='firm'?firmName(r.firm):r[f[0]]).join(' ').toLowerCase().includes(q));$('#table-body').innerHTML=rows.length?rows.map(r=>'<tr>'+fields.map(([k])=>`<td>${k==='status'?`<span class="tag">${escapeHtml(r[k])}</span>`:escapeHtml(k==='firm'?firmName(r[k]):r[k])}</td>`).join('')+`<td><button data-edit="${escapeHtml(r.id)}">Edit</button><button data-delete="${escapeHtml(r.id)}">Delete</button></td></tr>`).join(''):`<tr><td colspan="${fields.length+1}" class="empty">No records found.</td></tr>`}
function refresh(){renderJobs();renderCRM()}
function fieldHTML([k,label,type],record){let control;if(Array.isArray(type)||type==='firms'){const options=type==='firms'?db.firms.map(f=>[f.id,f.name]):type.map(t=>[t,t]);control=`<select name="${k}" required><option value="">Select ${escapeHtml(label.toLowerCase())}</option>${options.map(([value,text])=>`<option value="${escapeHtml(value)}" ${record[k]===value?'selected':''}>${escapeHtml(text)}</option>`).join('')}</select>`}else control=`<input name="${k}" type="${type==='number'?'number':type==='email'?'email':'text'}" ${type==='number'?'min="1" max="10000" step="1"':'maxlength="250"'} value="${escapeHtml(record[k]??'')}" required>`;return `<label>${escapeHtml(label)}${control}</label>`}
function openRecord(id=null){mode='record';editId=id;const r=db[tab].find(r=>r.id===id)||{};$('#dialog-title').textContent=(id?'Edit ':'Add ')+config[tab].singular;$('#record-fields').innerHTML=config[tab].fields.map(f=>fieldHTML(f,r)).join('');$('#form-status').textContent='';$('#record-dialog').showModal()}
$('#crm-open').onclick=()=>{$('#landing').hidden=true;$('#crm').hidden=false;refresh();window.scrollTo(0,0)};$('#crm-close').onclick=()=>{$('#landing').hidden=false;$('#crm').hidden=true;window.scrollTo(0,0)};$('#job-search').oninput=renderJobs;$('#sector-filter').onchange=renderJobs;$('#crm-search').oninput=renderCRM;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$('#crm-search').value='';renderCRM()});$('#add').onclick=()=>openRecord();$('#dialog-close').onclick=$('#cancel').onclick=()=>$('#record-dialog').close();
$('#table-body').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)openRecord(b.dataset.edit);if(b.dataset.delete){const id=b.dataset.delete;if(tab==='firms'&&db.jobs.some(j=>j.firm===id)){ $('#crm-status').textContent='This firm has linked openings. Reassign or delete those openings first.';return}if(confirm('Delete this demo record?')){db[tab]=db[tab].filter(r=>r.id!==id);save();refresh();$('#crm-status').textContent=storageAvailable?'Record deleted.':'Record deleted for this session only.'}}};
$('#record-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k in values)values[k]=values[k].trim();if(Object.values(values).some(v=>!v)){ $('#form-status').textContent='Please complete all fields with a valid value.';return}if(mode==='application'){db.enquiries.push({id:crypto.randomUUID(),name:values.name,company:applicationJob.title+' · '+firmName(applicationJob.firm),email:values.email,requirement:'Demo application: '+values.skill+' · '+values.location,status:'New'});save();$('#record-dialog').close();refresh();alert(storageAvailable?'Demo application saved in this browser. No application was sent.':'Demo application saved for this session only. No application was sent.');return}if(tab==='jobs'){values.vacancies=Number(values.vacancies);if(!Number.isInteger(values.vacancies)||values.vacancies<1||values.vacancies>10000||!db.firms.some(f=>f.id===values.firm)){ $('#form-status').textContent='Choose a valid firm and between 1 and 10,000 positions.';return}}if(editId){const i=db[tab].findIndex(r=>r.id===editId);db[tab][i]={...db[tab][i],...values}}else db[tab].push({id:crypto.randomUUID(),...values});save();$('#record-dialog').close();refresh();$('#crm-status').textContent=storageAvailable?'Record saved in this browser.':'Record saved for this session only.'};
$('#job-list').onclick=e=>{const b=e.target.closest('[data-apply]');if(!b)return;applicationJob=db.jobs.find(j=>j.id===b.dataset.apply);if(!applicationJob)return;mode='application';$('#dialog-title').textContent='Demo application';$('#record-fields').innerHTML=[['name','Full name'],['email','Email','email'],['skill','Role / skill'],['location','Location']].map(f=>fieldHTML(f,{})).join('');$('#form-status').textContent=applicationJob.title+' · Demo only. Nothing is sent.';$('#record-dialog').showModal()};
$('#enquiry-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k in values)values[k]=values[k].trim();if(Object.values(values).some(v=>!v)){ $('#enquiry-feedback').textContent='Please complete all fields.';return}db.enquiries.push({id:crypto.randomUUID(),...values,status:'New'});save();refresh();e.target.reset();$('#enquiry-feedback').textContent=storageAvailable?'Sample enquiry saved. View it in the CRM Enquiries tab. Nothing was sent.':'Sample enquiry saved for this session. Nothing was sent.'};
$('#reset').onclick=()=>{if(confirm('Restore all sample records and remove changes made in this browser?')){db=structuredClone(seed);save();refresh();$('#crm-status').textContent='Sample records restored.'}};
if(!db.seedUpdates?.additionalRoles){
  for(const firm of additionalFirms)if(!db.firms.some(f=>f.id===firm.id))db.firms.push(structuredClone(firm));
  for(const job of additionalJobs)if(!db.jobs.some(j=>j.id===job.id))db.jobs.push(structuredClone(job));
  db.seedUpdates={...db.seedUpdates,additionalRoles:true};save();
}
refresh();
